package com.bank.recon.service;

import java.util.logging.Logger;

// Target Sum reduced to counting subsets summing to (total + target) / 2.
public class ReconciliationService {
    private static final Logger log = Logger.getLogger(ReconciliationService.class.getName());

    public long countLabellings(int[] entries, int target) {
        int total = 0;
        for (int e : entries) total += e;
        if (total < Math.abs(target) || ((total + target) & 1) == 1) {
            log.warning(() -> "No labelling possible for target " + target);
            return 0;                                      // negative or odd → impossible
        }
        int subset = (total + target) / 2;                 // derived positive-group sum
        long[] dp = new long[subset + 1];
        dp[0] = 1;                                          // one empty way to make 0
        for (int num : entries) {
            for (int s = subset; s >= num; s--) {           // DOWNWARD → each entry once
                dp[s] += dp[s - num];                       // accumulate ways
            }
        }
        final long result = dp[subset];
        log.info(() -> "Labellings reaching target " + target + " = " + result);
        return dp[subset];
    }
}
