package com.bank.recon;

import com.bank.recon.service.ReconciliationService;
import java.util.logging.Logger;

public class ReconciliationApplication {
    private static final Logger log = Logger.getLogger(ReconciliationApplication.class.getName());

    public static void main(String[] args) {
        ReconciliationService service = new ReconciliationService();
        int[] entries = {1, 1, 1, 1, 1};                   // pending ledger entries
        long ways = service.countLabellings(entries, 3);  // target net = 3
        log.info(() -> "Final labelling count = " + ways);
    }
}
